<template>
  <div class="admin-shell">
    <el-container class="admin-layout">
      <el-aside class="admin-aside" width="270px">
        <div class="brand-block"><div class="brand-mark">FF</div><div><div class="brand-name">Football Admin</div><div class="brand-sub">{{ t('admin.dashboard.sidebar.brandSub') }}</div></div></div>
        <nav class="side-section" :aria-label="t('admin.dashboard.sidebar.navAria')"><div class="side-label">{{ t('admin.dashboard.sidebar.workbench') }}</div><el-menu :default-active="activeMenu" class="admin-menu" :aria-label="t('admin.dashboard.sidebar.menuAria')" @select="activeMenu = $event"><el-menu-item index="dashboard">{{ t('admin.dashboard.menu.overview') }}</el-menu-item><el-menu-item index="matches">{{ t('admin.dashboard.menu.matches') }}</el-menu-item><el-menu-item index="changelog">{{ t('admin.dashboard.menu.changelog') }}</el-menu-item><el-menu-item index="sources">{{ t('admin.dashboard.menu.sources') }}</el-menu-item><el-menu-item index="models">{{ t('admin.dashboard.menu.models') }}</el-menu-item><el-menu-item index="analytics">{{ t('admin.dashboard.menu.analytics') }}</el-menu-item><el-menu-item index="users">{{ t('admin.dashboard.menu.users') }}</el-menu-item><el-menu-item index="config">{{ t('admin.dashboard.menu.config') }}</el-menu-item><el-menu-item index="logs">{{ t('admin.dashboard.menu.logs') }}</el-menu-item></el-menu></nav>
        <div class="side-section side-meta"><div class="side-label">{{ t('admin.dashboard.sidebar.currentOverview') }}</div><div class="meta-item"><span>{{ t('admin.dashboard.sidebar.metaMatches') }}</span><strong>{{ crawlerMatchTotal }}</strong></div><div class="meta-item"><span>{{ t('admin.dashboard.sidebar.metaUsers') }}</span><strong>{{ users.length }}</strong></div><div class="meta-item"><span>{{ t('admin.dashboard.sidebar.metaAgentCompleted') }}</span><strong>{{ agentMetrics?.completed ?? '—' }}</strong></div><div class="meta-item"><span>{{ t('admin.dashboard.sidebar.metaLogs') }}</span><strong>{{ logs.length }}</strong></div></div>
      </el-aside>
      <el-container>
        <el-header class="admin-header"><div class="header-left"><span v-if="lastReloadAt" class="last-reload">{{ t('admin.dashboard.header.lastReload', { time: lastReloadAt }) }}</span></div><div class="header-actions"><el-input v-if="activeMenu === 'users'" v-model="userKeyword" class="head-search" :placeholder="t('admin.dashboard.header.searchUsers')" clearable @change="loadUsers" /><el-button @click="reloadAll">{{ t('admin.common.refresh') }}</el-button><el-button v-if="activeMenu === 'matches'" type="success" plain @click="syncMatchesNow">{{ t('admin.dashboard.header.sync') }}</el-button><el-button type="primary" plain @click="goFront">{{ t('admin.dashboard.header.backToSite') }}</el-button></div></el-header>
        <el-main id="app-main" class="admin-main" tabindex="-1">
          <el-alert v-if="activeMenu === 'dashboard' && sectionErrors.summary" class="summary-alert reveal" :title="sectionErrors.summary" type="warning" show-icon :closable="false" />
          <section v-if="activeMenu === 'dashboard'" class="dashboard-top reveal"><el-card v-for="item in metrics" :key="item.label" class="metric-card" shadow="never"><div class="metric-label">{{ item.label }}</div><div class="metric-value">{{ item.value }}</div><div class="metric-desc">{{ item.desc }}</div></el-card></section>
          <section v-if="activeMenu === 'dashboard'" class="dashboard-grid reveal">
            <el-card class="panel-card" shadow="never"><template #header><div class="panel-header"><span>{{ t('admin.dashboard.agent.title') }}</span><el-tag :type="agentHealth.status === 'ok' ? 'success' : 'warning'">{{ agentPolicyLabel }}</el-tag></div></template><div class="agent-metric-grid"><div><span>{{ t('admin.dashboard.agent.sent') }}</span><strong>{{ agentMetrics?.sent ?? '—' }}</strong></div><div><span>{{ t('admin.dashboard.agent.completed') }}</span><strong>{{ agentMetrics?.completed ?? '—' }}</strong></div><div><span>{{ t('admin.dashboard.agent.avgLatency') }}</span><strong>{{ agentMetrics?.avgLatencyMs ? `${agentMetrics.avgLatencyMs}ms` : '—' }}</strong></div><div><span>{{ t('admin.dashboard.agent.helpful') }}</span><strong>{{ agentMetrics?.feedback?.helpful ?? '—' }}</strong></div></div><div class="agent-policy-line">{{ t('admin.dashboard.agent.policyLine', { policy: agentPolicyDetail, thinking: t(globalModelPolicy.thinkingEnabled === false ? 'admin.common.off' : 'admin.common.on'), fallback: t(globalModelPolicy.fallbackEnabled === false ? 'admin.common.off' : 'admin.common.on') }) }}</div><div class="agent-provider-metrics"><span v-for="item in (agentMetrics?.providers || [])" :key="item.provider">{{ item.provider || 'unknown' }} · {{ item.total }}</span><span v-if="!(agentMetrics?.providers || []).length">{{ t('admin.dashboard.agent.noCalls') }}</span></div></el-card>
            <el-card class="panel-card" shadow="never"><template #header><div class="panel-header"><span>{{ t('admin.dashboard.crawler.title') }}</span><el-tag :type="sourceAttentionCount ? 'warning' : 'success'">{{ sourceAttentionCount ? t('admin.dashboard.crawler.attentionCount', { count: sourceAttentionCount }) : t('admin.dashboard.crawler.runningNormal') }}</el-tag></div></template><div class="source-monitor-summary">{{ t('admin.dashboard.crawler.primaryStatus', { source: primarySourceLabel, running: crawlerTaskSummary.running || 0, success: crawlerTaskSummary.success || 0, failed: crawlerTaskSummary.failed || 0 }) }}</div><div class="source-monitor-list"><div v-for="item in sourceHealthRows" :key="item.name" class="source-monitor-item"><span class="source-monitor-dot" :class="`is-${item.status.toLowerCase()}`"></span><div><strong>{{ item.label }}</strong><small>{{ item.statusText }} · {{ t('admin.dashboard.crawler.lastMatches', { count: item.lastMatchCount }) }}</small></div><el-tag size="small" :type="item.status === 'NORMAL' ? 'success' : 'warning'">{{ item.statusText }}</el-tag></div><el-empty v-if="!sourceHealthRows.length" :description="t('admin.dashboard.crawler.emptySources')" :image-size="48" /></div><div v-if="sourceAlerts.length" class="source-alert-list"><div v-for="alert in sourceAlerts.slice(0, 5)" :key="`${alert.source}-${alert.status}`" class="source-alert-item"><el-tag size="small" type="warning">{{ alert.severity || t('admin.dashboard.crawler.attention') }}</el-tag><span>{{ alert.source }} · {{ alert.message }}</span></div></div><div v-if="crawlerHistory.length" class="crawler-history"><small>{{ t('admin.dashboard.crawler.recentTasks') }}</small><span v-for="item in crawlerHistory.slice(0, 3)" :key="`${item.taskName}-${item.finishedAt}`">{{ item.taskName }} · {{ item.result }} · {{ t('admin.common.records', { count: item.processedCount || 0 }) }}</span></div></el-card>
            <el-card class="panel-card span-wide" shadow="never"><template #header><div class="panel-header"><span>{{ t('admin.dashboard.shortcuts.title') }}</span><el-tag type="info">Shortcuts</el-tag></div></template><div class="shortcut-grid"><el-button type="success" plain @click="activeMenu='matches'; openCrawlerMatchDialog()">{{ t('admin.dashboard.shortcuts.createMatch') }}</el-button><el-button type="primary" plain @click="activeMenu='matches'; syncMatchesNow()">{{ t('admin.dashboard.shortcuts.syncCrawler') }}</el-button><el-button type="warning" plain @click="activeMenu='users'">{{ t('admin.dashboard.shortcuts.manageUsers') }}</el-button><el-button type="info" plain @click="activeMenu='logs'">{{ t('admin.dashboard.shortcuts.viewLogs') }}</el-button></div></el-card>
            <el-card class="panel-card span-wide" shadow="never"><template #header><div class="panel-header"><span>{{ t('admin.dashboard.recent.title') }}</span><el-tag type="warning">Audit</el-tag></div></template><el-timeline><el-timeline-item v-for="item in recentLogs" :key="item.id || item.createdAt" :timestamp="item.createdAt" :type="item.result === 'SUCCESS' ? 'success' : 'danger'">{{ item.operatorName || t('admin.dashboard.recent.system') }} · {{ item.action || '-' }} · {{ item.content || '-' }}</el-timeline-item><el-empty v-if="!recentLogs.length" :description="t('admin.dashboard.recent.empty')" :image-size="48" /></el-timeline></el-card>
          </section>
          <section v-if="activeMenu === 'sources'" class="admin-panel-section source-console">
            <el-card class="panel-card" shadow="never"><template #header><div class="panel-header"><span>{{ t('admin.dashboard.sources.title') }}</span><el-tag :type="sourceAttentionCount ? 'warning' : 'success'">{{ sourceAttentionCount ? t('admin.dashboard.crawler.attentionCount', { count: sourceAttentionCount }) : t('admin.dashboard.crawler.sourceNormal') }}</el-tag></div></template>
              <el-alert :title="t('admin.dashboard.sources.notice')" type="info" :closable="false" show-icon />
              <div class="source-console-grid"><div v-for="item in sourceHealthRows" :key="item.name" class="source-console-card"><div class="source-console-card-head"><span class="source-monitor-dot" :class="`is-${item.status.toLowerCase()}`"></span><strong>{{ item.label }}</strong><el-tag size="small" :type="item.status === 'NORMAL' ? 'success' : item.status === 'EMPTY' ? 'info' : 'warning'">{{ item.statusText }}</el-tag></div><dl><div><dt>{{ t('admin.dashboard.sources.lastReturned') }}</dt><dd>{{ t('admin.common.matchesCount', { count: item.lastMatchCount }) }}</dd></div><div><dt>{{ t('admin.dashboard.sources.transport') }}</dt><dd>{{ item.transportHealthy === false ? t('admin.dashboard.sources.unavailable') : t('admin.dashboard.sources.available') }}</dd></div><div><dt>{{ t('admin.dashboard.sources.lastSuccess') }}</dt><dd>{{ formatAdminTime(item.lastSuccess) }}</dd></div><div><dt>{{ t('admin.dashboard.sources.dataAge') }}</dt><dd>{{ formatAge(item.dataAgeSeconds) }}</dd></div></dl></div><el-empty v-if="!sourceHealthRows.length" :description="t('admin.dashboard.sources.empty')" /></div>
              <div v-if="sourceAlerts.length" class="source-alert-list"><div v-for="alert in sourceAlerts" :key="`${alert.source}-${alert.status}-${alert.message}`" class="source-alert-item"><el-tag size="small" type="warning">{{ alert.severity || t('admin.dashboard.crawler.attention') }}</el-tag><span>{{ alert.source }} · {{ alert.message }}</span></div></div>
            </el-card>
          </section>
          <section v-if="activeMenu === 'models'" class="admin-panel-section model-lab">
            <el-card class="panel-card" shadow="never"><template #header><div class="panel-header"><span>{{ t('admin.dashboard.models.title') }}</span><el-tag type="info">{{ t('admin.dashboard.models.readonly') }}</el-tag></div></template>
              <el-alert :title="t('admin.dashboard.models.notice')" type="info" :closable="false" show-icon />
              <div class="model-lab-summary"><div><span>{{ t('admin.dashboard.models.window') }}</span><strong>{{ t('admin.common.daysCount', { count: modelPerformance.windowDays || 30 }) }}</strong></div><div><span>{{ t('admin.dashboard.models.validated') }}</span><strong>{{ t('admin.common.matchesCount', { count: modelPerformance.evaluated ?? '—' }) }}</strong></div><div><span>{{ t('admin.dashboard.models.accuracy') }}</span><strong>{{ modelAccuracy }}</strong></div><div><span>{{ t('admin.dashboard.models.productionVersion') }}</span><strong class="model-version">{{ (modelPerformance.modelVersions || [])[0] || t('admin.dashboard.models.unifiedSnapshot') }}</strong></div></div>
              <div class="model-lab-note"><el-icon><InfoFilled /></el-icon><span>{{ t('admin.dashboard.models.note') }}</span></div>
              <div v-if="modelPerformance.byLeague" class="model-league-list"><div v-for="(count, league) in modelPerformance.byLeague" :key="league"><span>{{ league }}</span><strong>{{ t('admin.dashboard.models.byLeague', { count }) }}</strong></div></div>
            </el-card>
          </section>
          <section v-if="activeMenu === 'analytics'" class="admin-panel-section analytics-console">
            <el-card class="panel-card" shadow="never"><template #header><div class="panel-header"><span>{{ t('admin.dashboard.analytics.title') }}</span><el-tag type="info">{{ t('admin.common.daysCount', { count: analyticsSummary.days || 7 }) }}</el-tag></div></template>
              <div class="analytics-summary-grid"><div><span>{{ t('admin.dashboard.analytics.totalEvents') }}</span><strong>{{ analyticsSummary.totalEvents ?? '—' }}</strong></div><div><span>{{ t('admin.dashboard.analytics.activeUsers') }}</span><strong>{{ analyticsSummary.uniqueUsers ?? '—' }}</strong></div><div><span>{{ t('admin.dashboard.analytics.trackingStatus') }}</span><strong>{{ analyticsSummary.status === 'AVAILABLE' ? t('admin.dashboard.analytics.available') : t('admin.dashboard.analytics.pendingInit') }}</strong></div></div>
              <el-alert v-if="analyticsSummary.status !== 'AVAILABLE'" :title="analyticsSummary.message || t('admin.dashboard.analytics.unavailable')" type="warning" :closable="false" show-icon />
              <div v-if="analyticsSummary.status === 'AVAILABLE'" class="analytics-funnel" :aria-label="t('admin.dashboard.analytics.funnelAria')"><span>{{ t('admin.dashboard.analytics.matchToPrediction') }} {{ analyticsSummary.funnel?.matchToPredictionRate ?? 0 }}%</span><span>{{ t('admin.dashboard.analytics.predictionToAgent') }} {{ analyticsSummary.funnel?.predictionToAgentRate ?? 0 }}%</span></div>
              <div v-if="analyticsSummary.status === 'AVAILABLE'" class="analytics-event-list"><div v-for="item in (analyticsSummary.eventCounts || [])" :key="item.event_name || item.eventName"><span>{{ item.event_name || item.eventName }}</span><strong>{{ item.total }}</strong></div><el-empty v-if="!(analyticsSummary.eventCounts || []).length" :description="t('admin.dashboard.analytics.noData')" /></div>
            </el-card>
          </section>
          <section v-if="activeMenu === 'matches'"><MatchWorkbench v-model:keyword="crawlerMatchKeyword" v-model:status="crawlerMatchStatus" v-model:date="crawlerMatchDate" :matches="crawlerMatches" :total="crawlerMatchTotal" :page="crawlerMatchPage" :page-size="crawlerMatchPageSize" :error="sectionErrors.matches" @reload="loadMatches" @size-change="handleCrawlerMatchSizeChange" @create="openCrawlerMatchDialog()" @edit="openCrawlerMatchDialog" @delete="deleteCrawlerMatch" /></section>
          <section v-if="activeMenu === 'changelog'"><AdminChangelogPanel /></section>
          <section v-if="activeMenu === 'users'" class="admin-panel-section"><AdminUsersPanel :users="users" v-model:role-filter="userRoleFilter" v-model:status-filter="userStatusFilter" :error="sectionErrors.users" @filter-change="loadUsers" @retry="loadUsers" @user-action="handleUserCommand" /></section>
          <section v-if="activeMenu === 'config'" class="admin-panel-section"><AdminConfigPanel :config="config" :error="sectionErrors.config" @save="saveConfig" @retry="loadConfig" /></section>
          <section v-if="activeMenu === 'logs'" class="admin-panel-section"><AdminLogPanel :logs="logs" v-model:module-filter="logModuleFilter" :error="sectionErrors.logs" @filter-change="loadLogs" @retry="loadLogs" @open-detail="openLogDetail" /></section>
        </el-main>
      </el-container>
    </el-container>
    <AdminCrawlerMatchEditorDialog v-model="crawlerMatchDialogVisible" :form="crawlerMatchForm" @save="saveCrawlerMatch" />
    <el-dialog v-model="syncProgressVisible" :title="t('admin.dashboard.sync.title')" width="680px" :close-on-click-modal="!syncRunning" :close-on-press-escape="!syncRunning" :show-close="!syncRunning" class="admin-dialog sync-dialog"><div class="sync-progress-head"><div><div class="sync-progress-title">{{ syncProgressTitle }}</div><div class="sync-progress-subtitle">{{ syncProgressSubtitle }}</div></div><el-tag :type="syncRunning ? 'warning' : (syncProgressFailed ? 'danger' : 'success')">{{ syncRunning ? t('admin.dashboard.sync.syncing') : (syncProgressFailed ? t('admin.dashboard.sync.failed') : t('admin.dashboard.sync.completed')) }}</el-tag></div><el-progress :percentage="syncProgressPercent" :status="syncProgressFailed && !syncRunning ? 'exception' : (syncRunning ? undefined : 'success')" :stroke-width="14" striped striped-flow /><div class="sync-source-list"><div v-for="item in syncProgressSources" :key="item.key" class="sync-source-item"><div class="sync-source-main"><span class="sync-dot" :class="`is-${item.status}`"></span><div><strong>{{ item.label }}</strong><p>{{ item.message }}</p></div></div><el-tag size="small" :type="syncStatusTag(item.status)">{{ syncStatusText(item.status) }}</el-tag></div></div><template #footer><el-button :disabled="syncRunning" @click="syncProgressVisible=false">{{ t('admin.dashboard.sync.close') }}</el-button><el-button type="primary" :loading="syncRunning" @click="syncMatchesNow">{{ syncRunning ? t('admin.dashboard.sync.syncingButton') : t('admin.dashboard.sync.resync') }}</el-button></template></el-dialog>
    <el-drawer v-model="logDetailVisible" :title="t('admin.dashboard.logDetail.title')" size="460px"><el-descriptions :column="1" size="small" border><el-descriptions-item :label="t('admin.dashboard.logDetail.time')">{{ currentLog.createdAt || '-' }}</el-descriptions-item><el-descriptions-item :label="t('admin.dashboard.logDetail.operator')">{{ currentLog.operatorName || '-' }}</el-descriptions-item><el-descriptions-item :label="t('admin.dashboard.logDetail.module')">{{ currentLog.module || '-' }}</el-descriptions-item><el-descriptions-item :label="t('admin.dashboard.logDetail.action')">{{ currentLog.action || '-' }}</el-descriptions-item><el-descriptions-item :label="t('admin.dashboard.logDetail.targetType')">{{ currentLog.targetType || '-' }}</el-descriptions-item><el-descriptions-item :label="t('admin.dashboard.logDetail.targetId')">{{ currentLog.targetId || '-' }}</el-descriptions-item><el-descriptions-item :label="t('admin.dashboard.logDetail.content')">{{ currentLog.content || '-' }}</el-descriptions-item><el-descriptions-item :label="t('admin.dashboard.logDetail.result')"><el-tag :type="currentLog.result === 'SUCCESS' ? 'success' : 'danger'">{{ currentLog.result || '-' }}</el-tag></el-descriptions-item></el-descriptions></el-drawer>
  </div>
</template>

<script setup>
import { computed, defineAsyncComponent, getCurrentInstance, onMounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { InfoFilled } from '@element-plus/icons-vue'
import { adminApi } from '../../api/admin'
import { registerElementPlusAdmin } from '../../plugins/register-element-plus-admin'
import { agentApi, crawlerApi, predictionApi } from '../../api'
import { useI18n } from '../../i18n'

registerElementPlusAdmin(getCurrentInstance()?.appContext.app)

const { t, locale } = useI18n()

const AdminConfigPanel = defineAsyncComponent(() => import('./AdminConfigPanel.vue'))
const AdminChangelogPanel = defineAsyncComponent(() => import('./AdminChangelogPanel.vue'))
const AdminCrawlerMatchEditorDialog = defineAsyncComponent(() => import('./AdminCrawlerMatchEditorDialog.vue'))
const AdminLogPanel = defineAsyncComponent(() => import('./AdminLogPanel.vue'))
const AdminUsersPanel = defineAsyncComponent(() => import('./AdminUsersPanel.vue'))
const MatchWorkbench = defineAsyncComponent(() => import('./MatchWorkbench.vue'))

const router = useRouter()
const activeMenu = ref('dashboard')
const crawlerMatches = ref([])
const crawlerMatchTotal = ref(0)
const crawlerMatchPage = ref(1)
const crawlerMatchPageSize = ref(20)
const crawlerMatchKeyword = ref('')
const crawlerMatchStatus = ref('')
const crawlerMatchDate = ref('')
const crawlerMatchDialogVisible = ref(false)
const crawlerMatchForm = reactive({})
const users = ref([])
const logs = ref([])
const config = reactive({})
const userKeyword = ref('')
const userRoleFilter = ref('')
const userStatusFilter = ref('')
const logModuleFilter = ref('')
const dataSourceHealth = ref({ providers: [], primaryOnly: true, primarySource: 'bbc-scores' })
const crawlerHealth = ref({ taskSummary: {}, history: [] })
const agentMetrics = ref(null)
const agentHealth = ref({ status: 'unknown', models: {} })
const modelPerformance = ref({})
const analyticsSummary = ref({})
const sectionErrors = reactive({ matches: '', users: '', config: '', logs: '', summary: '' })
const syncProgressVisible = ref(false)
const syncRunning = ref(false)
const syncProgressFailed = ref(false)
const syncProgressTitle = ref('')
const syncProgressSubtitle = ref('')
const syncProgressPercent = ref(0)
const syncProgressSources = ref([])
const logDetailVisible = ref(false)
const currentLog = reactive({})
const dashboardTodayMatches = ref([])
const lastReloadAt = ref('')

const pageTitle = computed(() => ({
  dashboard: t('admin.dashboard.page.dashboard'),
  matches: t('admin.dashboard.page.matches'),
  changelog: t('admin.dashboard.page.changelog'),
  sources: t('admin.dashboard.page.sources'),
  models: t('admin.dashboard.page.models'),
  analytics: t('admin.dashboard.page.analytics'),
  users: t('admin.dashboard.page.users'),
  config: t('admin.dashboard.page.config'),
  logs: t('admin.dashboard.page.logs')
}[activeMenu.value]))
const activeUserCount = computed(() => users.value.filter(user => user.status === 'ACTIVE').length)
const todaysMatchCount = computed(() => dashboardTodayMatches.value.length)
const metrics = computed(() => [
  { label: t('admin.dashboard.metrics.todayMatches'), value: todaysMatchCount.value, desc: t('admin.dashboard.metrics.todayDesc') },
  { label: t('admin.dashboard.metrics.totalMatches'), value: crawlerMatchTotal.value, desc: t('admin.dashboard.metrics.totalDesc') },
  { label: t('admin.dashboard.metrics.activeUsers'), value: activeUserCount.value, desc: t('admin.dashboard.metrics.activeDesc') },
  { label: t('admin.dashboard.metrics.auditLogs'), value: logs.value.length, desc: t('admin.dashboard.metrics.auditDesc') }
])
const globalModelPolicy = computed(() => agentHealth.value?.models?.configuredPolicy || {})
const agentPolicyDetail = computed(() => { const policy = globalModelPolicy.value; const configured = String(policy.provider || 'auto').toLowerCase(); const providerItems = agentHealth.value?.models?.providers || []; const ready = name => providerItems.some(item => item.provider === name && item.configured); const provider = configured === 'openrouter' && ready('openrouter') ? 'openrouter' : configured === 'scnet' && ready('scnet') ? 'scnet' : configured === 'deepseek' && ready('deepseek') ? 'deepseek' : ready('openrouter') ? 'openrouter' : ready('scnet') ? 'scnet' : 'deepseek'; const labels = { openrouter: 'OpenRouter', scnet: 'SCNet', deepseek: 'DeepSeek' }; const model = policy[provider]?.model || providerItems.find(item => item.provider === provider)?.model || t('admin.dashboard.agent.defaultEnvModel'); return `${labels[provider] || provider} · ${model}` })
const agentPolicyLabel = computed(() => agentHealth.value.status === 'ok' ? t('admin.dashboard.agent.online') : t('admin.dashboard.agent.attention'))
const primarySourceLabel = computed(() => dataSourceHealth.value.primarySource || 'bbc-scores')
const sourceHealthRows = computed(() => (Array.isArray(dataSourceHealth.value?.providers) ? dataSourceHealth.value.providers : []).filter(item => item.enabled !== false).map(item => ({ name: item.name || item.source || 'unknown', label: item.name === 'bbc-scores' ? t('admin.dashboard.crawler.primaryBbc') : item.name || item.source || t('admin.dashboard.crawler.dataSource'), status: String(item.status || 'UNKNOWN'), statusText: item.statusText || t('admin.dashboard.crawler.notDetected'), lastMatchCount: Number(item.lastMatchCount || 0), transportHealthy: item.transportHealthy, lastSuccess: item.lastSuccess, dataAgeSeconds: item.dataAgeSeconds })))
const sourceAttentionCount = computed(() => sourceHealthRows.value.filter(item => item.status !== 'NORMAL').length)
const crawlerTaskSummary = computed(() => crawlerHealth.value?.taskSummary || {})
const sourceAlerts = computed(() => Array.isArray(dataSourceHealth.value?.alerts) ? dataSourceHealth.value.alerts : [])
const crawlerHistory = computed(() => Array.isArray(crawlerHealth.value?.history) ? crawlerHealth.value.history : [])
const recentLogs = computed(() => logs.value.slice(0, 5))
const modelAccuracy = computed(() => modelPerformance.value.accuracy == null ? '—' : `${Number(modelPerformance.value.accuracy).toFixed(1)}%`)
const formatAdminTime = value => value ? new Date(value).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : '—'
const formatAge = value => { const seconds = Number(value); if (!Number.isFinite(seconds) || seconds < 0) return '—'; if (seconds < 60) return t('admin.dashboard.age.seconds', { count: Math.round(seconds) }); if (seconds < 3600) return t('admin.dashboard.age.minutes', { count: Math.round(seconds / 60) }); return t('admin.dashboard.age.hours', { count: Math.round(seconds / 3600) }) }

const normalizePageResult = res => {
  if (Array.isArray(res)) return { items: res, total: res.length }
  if (res && Array.isArray(res.items)) return res
  if (res && Array.isArray(res.response)) return { ...res, items: res.response, total: Number(res.total ?? res.response.length) }
  if (res && Array.isArray(res.records)) return { ...res, items: res.records, total: Number(res.total ?? res.records.length) }
  if (res && Array.isArray(res.data?.items)) return res.data
  if (res && Array.isArray(res.data?.response)) return { ...res.data, items: res.data.response, total: Number(res.data.total ?? res.data.response.length) }
  return { items: [], total: 0 }
}
const mapCrawlerMatchRow = row => ({ id: row?.id ?? row?.fixture?.id ?? row?.fixtureId ?? null, fixtureId: row?.fixture?.id ?? row?.fixtureId ?? row?.id ?? null, externalMatchId: row?.externalMatchId ?? row?.external_id ?? '', source: row?.source ?? '', leagueId: row?.league?.id ?? row?.leagueId ?? '', leagueName: row?.league?.name ?? row?.leagueName ?? '', homeTeamId: row?.teams?.home?.id ?? row?.homeTeamId ?? '', homeTeamName: row?.teams?.home?.name ?? row?.homeTeamName ?? '', homeTeamLogo: row?.teams?.home?.logo ?? row?.homeTeamLogo ?? '', awayTeamId: row?.teams?.away?.id ?? row?.awayTeamId ?? '', awayTeamName: row?.teams?.away?.name ?? row?.awayTeamName ?? '', awayTeamLogo: row?.teams?.away?.logo ?? row?.awayTeamLogo ?? '', homeScore: row?.goals?.home ?? row?.homeScore ?? null, awayScore: row?.goals?.away ?? row?.awayScore ?? null, status: row?.fixture?.status?.short ?? row?.status ?? '', matchTime: row?.fixture?.date ?? row?.matchTime ?? '', matchDate: row?.fixture?.date ? String(row.fixture.date).slice(0, 10) : (row?.matchTime ? String(row.matchTime).slice(0, 10) : ''), note: row?.note ?? '' })
const loadMatches = async (page = crawlerMatchPage.value) => { sectionErrors.matches = ''; try { crawlerMatchPage.value = page; const result = normalizePageResult(await adminApi.listCrawlerMatches({ keyword: crawlerMatchKeyword.value, status: crawlerMatchStatus.value, date: crawlerMatchDate.value, page, size: crawlerMatchPageSize.value })); crawlerMatches.value = result.items.map(mapCrawlerMatchRow); crawlerMatchTotal.value = Number(result.total || 0) } catch (error) { sectionErrors.matches = error?.message || t('admin.dashboard.err.matchesService'); crawlerMatches.value = []; crawlerMatchTotal.value = 0 } }
const loadUsers = async () => { sectionErrors.users = ''; try { let result = await adminApi.listUsers(userKeyword.value); if (userRoleFilter.value) result = result.filter(user => user.role === userRoleFilter.value); if (userStatusFilter.value) result = result.filter(user => user.status === userStatusFilter.value); users.value = result } catch (error) { sectionErrors.users = error?.message || t('admin.dashboard.err.usersService'); users.value = [] } }
const loadConfig = async () => { sectionErrors.config = ''; try { Object.assign(config, await adminApi.getConfig()) } catch (error) { sectionErrors.config = error?.message || t('admin.dashboard.err.configService') } }
const loadLogs = async () => { sectionErrors.logs = ''; try { const result = await adminApi.getLogs(); logs.value = logModuleFilter.value ? result.filter(item => item.module === logModuleFilter.value) : result } catch (error) { sectionErrors.logs = error?.message || t('admin.dashboard.err.logsService'); logs.value = [] } }
const unwrap = result => result?.data || result || {}
const normalizeList = result => { const value = unwrap(result); return Array.isArray(value) ? value : Array.isArray(value.items) ? value.items : Array.isArray(value.response) ? value.response : [] }
const loadDashboardSummary = async () => { sectionErrors.summary = ''; const [matchesResult, healthResult, crawlerResult, metricsResult, agentResult, modelResult, analyticsResult] = await Promise.allSettled([crawlerApi.getTodayMatches(), crawlerApi.getDataSourceHealth(), crawlerApi.getHealth(), agentApi.metrics(7), agentApi.health(), predictionApi.getPerformance(30), adminApi.getAnalyticsSummary(7)]); const errors = []; if (matchesResult.status === 'fulfilled') dashboardTodayMatches.value = normalizeList(matchesResult.value); else errors.push(t('admin.dashboard.summary.todayMatches', { message: matchesResult.reason?.message || t('admin.dashboard.err.loadFailed') })); if (healthResult.status === 'fulfilled') dataSourceHealth.value = unwrap(healthResult.value) || { providers: [] }; else errors.push(t('admin.dashboard.summary.dataSourceHealth', { message: healthResult.reason?.message || t('admin.dashboard.err.loadFailed') })); if (crawlerResult.status === 'fulfilled') crawlerHealth.value = unwrap(crawlerResult.value) || { taskSummary: {} }; else errors.push(t('admin.dashboard.summary.taskStatus', { message: crawlerResult.reason?.message || t('admin.dashboard.err.loadFailed') })); if (metricsResult.status === 'fulfilled') agentMetrics.value = unwrap(metricsResult.value); if (agentResult.status === 'fulfilled') agentHealth.value = unwrap(agentResult.value) || { status: 'unknown', models: {} }; else errors.push(t('admin.dashboard.summary.agentStatus', { message: agentResult.reason?.message || t('admin.dashboard.err.loadFailed') })); if (modelResult.status === 'fulfilled') modelPerformance.value = unwrap(modelResult.value) || {}; if (analyticsResult.status === 'fulfilled') analyticsSummary.value = unwrap(analyticsResult.value) || {}; sectionErrors.summary = errors.join(t('admin.common.errorSeparator')) }
const loadDashboard = async () => { await Promise.allSettled([loadMatches(1), loadUsers(), loadConfig(), loadLogs(), loadDashboardSummary()]); return Object.values(sectionErrors).every(value => !value) }
const reloadAll = async () => { const ok = await loadDashboard(); lastReloadAt.value = formatAdminTime(new Date()); if (ok) ElMessage.success(t('admin.dashboard.msg.refreshed')); else ElMessage.warning(t('admin.dashboard.msg.refreshPartial')); return ok }
const goFront = () => router.push('/matches')
const handleCrawlerMatchSizeChange = size => { crawlerMatchPageSize.value = size; loadMatches(1) }
const createNewFixtureId = () => Date.now()
const splitMatchDateTime = value => { if (!value) return { matchDate: '', matchTime: '' }; const text = String(value); const [datePart, timePart = ''] = text.includes('T') ? text.split('T') : text.split(' '); return { matchDate: datePart || '', matchTime: (timePart || '').slice(0, 8) } }
const openCrawlerMatchDialog = (row = null) => { const mapped = row ? mapCrawlerMatchRow(row) : {}; const dt = splitMatchDateTime(mapped.matchTime || row?.matchTime); Object.assign(crawlerMatchForm, { id: row?.id ?? null, fixtureId: row?.fixtureId ?? createNewFixtureId(), externalMatchId: row?.externalMatchId || mapped.externalMatchId || '', source: row?.source || 'bbc-scores', leagueId: '', leagueName: '', round: '', venue: '', homeTeamId: '', homeTeamName: '', homeTeamLogo: '', awayTeamId: '', awayTeamName: '', awayTeamLogo: '', homeScore: null, awayScore: null, status: 'NS', matchDate: dt.matchDate, matchTime: dt.matchTime, note: '', ...mapped, matchDate: row ? dt.matchDate : '', matchTime: row ? dt.matchTime : '' }); crawlerMatchDialogVisible.value = true }
const saveCrawlerMatch = async () => { const matchTime = crawlerMatchForm.matchDate ? `${crawlerMatchForm.matchDate}T${(crawlerMatchForm.matchTime || '00:00:00').slice(0, 8)}` : (crawlerMatchForm.matchTime || null); const payload = { ...crawlerMatchForm, fixtureId: crawlerMatchForm.fixtureId ? Number(crawlerMatchForm.fixtureId) : null, externalMatchId: crawlerMatchForm.externalMatchId || String(crawlerMatchForm.fixtureId || ''), matchTime, homeScore: crawlerMatchForm.homeScore === '' || crawlerMatchForm.homeScore == null ? null : Number(crawlerMatchForm.homeScore), awayScore: crawlerMatchForm.awayScore === '' || crawlerMatchForm.awayScore == null ? null : Number(crawlerMatchForm.awayScore) }; if (payload.id) await adminApi.updateCrawlerMatch(payload.id, payload); else await adminApi.saveCrawlerMatch(payload); crawlerMatchDialogVisible.value = false; await loadMatches(crawlerMatchPage.value); ElMessage.success(t('admin.dashboard.msg.matchSaved')) }
const deleteCrawlerMatch = async row => { const id = row?.id; if (!id) { ElMessage.warning(t('admin.dashboard.msg.matchIdMissing')); return } await ElMessageBox.confirm(t('admin.dashboard.msg.confirmDeleteMatch'), t('admin.dashboard.msg.deleteMatchTitle')); await adminApi.deleteCrawlerMatch(id); await loadMatches(crawlerMatchPage.value); ElMessage.success(t('admin.dashboard.msg.matchDeleted')) }
const handleUserCommand = async (command, row) => { if (command === 'toggleRole') await adminApi.updateUserRole(row.id, row.role === 'ADMIN' ? 'USER' : 'ADMIN'); if (command === 'toggleStatus') await adminApi.updateUserStatus(row.id, row.status === 'ACTIVE' ? 'DISABLED' : 'ACTIVE'); await loadUsers() }
const saveConfig = async () => { await adminApi.saveConfig(config); await loadConfig(); ElMessage.success(t('admin.dashboard.msg.configSaved')) }
const syncTasks = computed(() => [{ key: 'bbc-scores', label: t('admin.dashboard.sync.taskBbc'), action: () => adminApi.syncUpcomingMatches() }])
const resetSyncProgress = () => { syncProgressFailed.value = false; syncProgressPercent.value = 0; syncProgressTitle.value = t('admin.dashboard.sync.preparingTitle'); syncProgressSubtitle.value = t('admin.dashboard.sync.preparingSubtitle'); syncProgressSources.value = syncTasks.value.map(item => ({ ...item, status: 'pending', message: t('admin.dashboard.sync.waiting') })) }
const updateSyncPercent = () => { const done = syncProgressSources.value.filter(item => ['success', 'error'].includes(item.status)).length; syncProgressPercent.value = syncProgressSources.value.length ? Math.round(done / syncProgressSources.value.length * 100) : 0 }
const syncStatusTag = status => ({ pending: 'info', running: 'warning', success: 'success', error: 'danger' }[status] || 'info')
const syncStatusText = status => ({ pending: t('admin.dashboard.sync.pending'), running: t('admin.dashboard.sync.running'), success: t('admin.dashboard.sync.success'), error: t('admin.dashboard.sync.error') }[status] || status)
const syncMatchesNow = async () => { if (syncRunning.value) return; resetSyncProgress(); syncProgressVisible.value = true; syncRunning.value = true; try { for (const task of syncTasks.value) { syncProgressTitle.value = t('admin.dashboard.sync.syncingTask', { task: task.label }); syncProgressSources.value = syncProgressSources.value.map(item => item.key === task.key ? { ...item, status: 'running', message: t('admin.dashboard.sync.requesting') } : item); try { const report = unwrap(await task.action()); syncProgressSources.value = syncProgressSources.value.map(item => item.key === task.key ? { ...item, status: 'success', message: t('admin.dashboard.sync.reportDone', { total: report?.total || 0, inserted: report?.inserted || 0, updated: report?.updated || 0 }) } : item) } catch (error) { syncProgressFailed.value = true; const message = error?.response?.status === 504 ? t('admin.dashboard.sync.timeout') : (error?.response?.data?.message || error?.message || t('admin.dashboard.sync.failedFallback')); syncProgressSources.value = syncProgressSources.value.map(item => item.key === task.key ? { ...item, status: 'error', message } : item) } updateSyncPercent() } syncProgressTitle.value = syncProgressFailed.value ? t('admin.dashboard.sync.failedTitle') : t('admin.dashboard.sync.successTitle'); syncProgressSubtitle.value = syncProgressFailed.value ? t('admin.dashboard.sync.failedSubtitle') : t('admin.dashboard.sync.refreshingSubtitle'); if (syncProgressFailed.value) ElMessage.warning(t('admin.dashboard.msg.primarySyncFailed')); else ElMessage.success(t('admin.dashboard.msg.primarySyncCompleted')) } finally { syncRunning.value = false; syncProgressPercent.value = 100; await loadMatches(crawlerMatchPage.value); await loadDashboardSummary() } }
const openLogDetail = row => { Object.assign(currentLog, row || {}); logDetailVisible.value = true }
onMounted(async () => { await loadDashboard(); lastReloadAt.value = formatAdminTime(new Date()) })
watch(locale, async () => { await loadDashboard(); lastReloadAt.value = formatAdminTime(new Date()) })
</script>

